    memset(level, 0, sizeof(level));
    queue<int> q;
    q.push(s);
    cur[s] = head[s];
    level[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = head[u]; i != -1; i = edge[i].next) {
            int v = edge[i].to;
            int w = edge[i].w;
            if (level[v] || !w) continue;
            level[v] = level[u] + 1;
            cur[v] = head[v];
            q.push(v);
            if (v == t) return true;
        }
    }
    return false;
}

int dfs(int x, int t, int flow) {
    if (x == t) return flow;
    int rest = flow;
    for (int &i = cur[x]; i != -1 && rest; i = edge[i].next) {
        int v = edge[i].to;
        int w = edge[i].w;
        if (w && level[v] == level[x] + 1) {
            int k = dfs(v, t, min(rest, w));
            if (!k) level[v] = 0;
            edge[i].w -= k;
            edge[i ^ 1].w += k;
            rest -= k;
        }
    }
    return flow - rest;
}

int dinic(int s, int t) {
    int ans = 0, flow;
    while (bfs(s, t))
        while (flow = dfs(s, t, INF))
            ans += flow;
    return ans;
}

int getId(int x, int y, int k) {
    return (x - 1) * n + y + k * n * n;
}

void explore(int sx, int sy, int cx, int cy, int step) {
    vis[cx][cy] = true;
