    static final int INF = Integer.MAX_VALUE / 2;
    static final int MAXN = 210;
    static final int MAXE = MAXN * MAXN;
    static final int[][] dir = {{0,1},{0,-1},{1,0},{-1,0}};

    static int n, T;
    static int src = MAXN - 1;
    static int sink = src - 1;
    static int[][] sci;
    static int[][] cap;
    static int[][][] maze;
    static boolean[][][][][] dp;
    static boolean[][] vis;
    static int[] head;
    static int[] to, w, next;
    static int cnt;
    static int[] level, cur;

    static void addEdge(int u, int v, int weight) {
        to[cnt] = v;
        w[cnt] = weight;
        next[cnt] = head[u];
        head[u] = cnt++;
        to[cnt] = u;
        w[cnt] = 0;
        next[cnt] = head[v];
        head[v] = cnt++;
    }

    static boolean bfs(int s, int t) {
        Arrays.fill(level, 0);
        Queue<Integer> q = new ArrayDeque<>();
        q.add(s);
        cur[s] = head[s];
        level[s] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int i = head[u]; i != -1; i = next[i]) {
                int v = to[i];
                int weight = w[i];
                if (level[v] != 0 || weight == 0) continue;
                level[v] = level[u] + 1;
                cur[v] = head[v];
                q.add(v);
                if (v == t) return true;
            }
        }
        return false;
    }

    static int dfs(int x, int t, int flow) {
        if (x == t) return flow;
        int rest = flow;
        for (int i = cur[x]; i != -1 && rest > 0; i = next[i]) {
            int v = to[i];
            int weight = w[i];
            if (weight > 0 && level[v] == level[x] + 1) {
                int k = dfs(v, t, Math.min(rest, weight));
                if (k == 0) level[v] = 0;
                w[i] -= k;
                w[i ^ 1] += k;
                rest -= k;
            }
            cur[x] = next[i];
        }
        return flow - rest;
    }

    static int dinic(int s, int t) {
        int ans = 0;
        int flow;
        while (bfs(s, t)) {
            while ((flow = dfs(s, t, INF)) > 0) {
                ans += flow;
            }
        }
        return ans;
    }

    static int getId(int x, int y, int k) {
        return (x - 1) * n + y + k * n * n;
    }

    static void explore(int sx, int sy, int cx, int cy, int step) {
        vis[cx][cy] = true;
        dp[step][sx][sy][cx][cy] = true;
        if (step >= T || maze[step][cx][cy] != 0) return;
        for (int d = 0; d < 4; ++d) {
            int nx = cx + dir[d][0];
            int ny = cy + dir[d][1];
            if (nx < 1 || ny < 1 || nx > n || ny > n) continue;
            if (vis[nx][ny] || maze[step][nx][ny] != 0) continue;
            explore(sx, sy, nx, ny, step + 1);
        }
    }

    static void init() {
        Arrays.fill(cur, 0);
        Arrays.fill(head, -1);
        cnt = 0;
        for (int time = 1; time <= T; ++time) {
            for (int x = 1; x <= n; ++x) {
                for (int y = 1; y <= n; ++y) {
                    if (maze[time - 1][x][y] != 0) {
                        maze[time][x][y] = maze[time - 1][x][y];
                    } else {
                        for (int d = 0; d < 4; ++d) {
                            int xx = x + dir[d][0];
                            int yy = y + dir[d][1];
                            if (xx < 1 || yy < 1 || xx > n || yy > n) continue;
                            if (maze[time - 1][xx][yy] == 2) {
                                maze[time][x][y] = 2;
                            }
                        }
                    }
                }
            }
        }
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (sci[i][j] != 0) {
                    for (int a = 1; a <= n; ++a) Arrays.fill(vis[a], false);
                    explore(i, j, i, j, 0);
                }
            }
        }
        for (int i = 1; i <= T; ++i) {
            for (int x = 1; x <= n; ++x) {
                for (int y = 1; y <= n; ++y) {
                    for (int xx = 1; xx <= n; ++xx) {
                        for (int yy = 1; yy <= n; ++yy) {
                            dp[i][x][y][xx][yy] |= dp[i - 1][x][y][xx][yy];
                        }
                    }
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
